// ---------------------------------------------------------------------------
// Persistent profile store (prototype).
// Identity = random device token generated by the browser (NOT secure auth).
// Stores: display name, appearance, friends (by name), owned house.
// NOTE: real accounts/auth is a documented production roadmap item.
// ---------------------------------------------------------------------------
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
// DATA_DIR is an explicit test/deployment override; production uses ./data.
const DATA_DIR = process.env.DATA_DIR
  ? path.resolve(process.env.DATA_DIR)
  : path.join(__dirname, '..', 'data');
const FILE = path.join(DATA_DIR, 'profiles.json');

let profiles = {};
let saveTimer = null;

export function initStore() {
  fs.mkdirSync(DATA_DIR, { recursive: true });
  try {
    profiles = JSON.parse(fs.readFileSync(FILE, 'utf8'));
  } catch {
    profiles = {}; // fresh or corrupt file -> start clean (prototype store)
  }
  return Object.keys(profiles).length;
}

export function getProfile(token) {
  if (!/^[a-f0-9]{16,64}$/.test(String(token || ''))) return null;
  return profiles[token] ?? null;
}

export function upsertProfile(token, patch) {
  if (!/^[a-f0-9]{16,64}$/.test(String(token || ''))) return null;
  const p = profiles[token] ?? { created: Date.now(), friends: [] };
  profiles[token] = Object.assign(p, patch);
  scheduleSave();
  return profiles[token];
}

// ---- Friends (by display name for this prototype) --------------------------
export function addFriend(token, name) {
  const p = getProfile(token);
  if (!p) return false;
  if (!p.friends.includes(name)) p.friends.push(name);
  scheduleSave();
  return true;
}

export function removeFriend(token, name) {
  const p = getProfile(token);
  if (!p || !p.friends.includes(name)) return false;
  p.friends = p.friends.filter((f) => f !== name);
  scheduleSave();
  return true;
}

export function isFriend(ownerToken, name) {
  const p = getProfile(ownerToken);
  return !!p && p.friends.includes(name);
}

// Online presence of a friend name across all rooms.
export function findOnlineByName(roomIndex, name) {
  for (const room of roomIndex.values()) {
    for (const pl of room.players.values()) {
      if (pl.name === name && pl.socket) return pl;
    }
  }
  return null;
}

function scheduleSave() {
  if (saveTimer) return;
  saveTimer = setTimeout(() => {
    saveTimer = null;
    try {
      fs.writeFileSync(FILE + '.tmp', JSON.stringify(profiles));
      fs.renameSync(FILE + '.tmp', FILE);
    } catch (e) {
      console.error('[store] save failed:', e.message);
    }
  }, 500);
}
